// Isolated synthetic fixture host. Not shipped in the desktop app.
const fs=require('node:fs'),path=require('node:path'),readline=require('node:readline'),{randomUUID}=require('node:crypto');
require('./offline-only.cjs');
const {Studio}=require(path.resolve('output/unified-plan-integration/core.cjs'));
const {draft}=require('./workflow.cjs');
const root=path.resolve(process.argv[2]);if(!root.includes('output')||!root.includes('plan-center-headless'))throw Error('ISOLATED_FIXTURE_ROOT_REQUIRED');
const s=new Studio(root,'production'),artist=s.all('artists')[0];s.save('artists',{...artist,name:'离线演示创作者'});
const channelId=randomUUID(),textProfile=randomUUID(),musicProfile=randomUUID(),accountId=randomUUID();
s.save('settings',{id:'inbox-channel',enabled:true,revision:1,channel:{id:channelId,workspaceId:randomUUID(),workspaceRef:'offline-demo',artistRefs:{creator:artist.id},seriesRefs:{}}});
for(const [id,kind,providerId,modelId,label] of [[textProfile,'text','deepseek','deepseek-flash','离线文本配置'],[musicProfile,'music','yourmusic','chirp-v6','离线音乐配置']])s.save('settings',{id:'api-profile:'+id,kind,providerId,modelId,label,revision:1,executionEnabled:false});
s.save('accounts',{id:accountId,provider:'tme',label:'离线演示账号',authStatus:'unavailable',scopes:[],identitySource:'synthetic-fixture',remoteSubject:'f'.repeat(64)});
const {createPlanAlbumBroker,executeInternalPlanAlbums,validate}=require(path.resolve('output/album-integration/full-ui-main.cjs'));
const albumBroker=createPlanAlbumBroker({available:()=>true,generation:()=>1,getSession:()=>undefined,rpc:async(method,input)=>{try{return{ok:true,value:method.startsWith('internal.planAlbums.')?executeInternalPlanAlbums(s,method.slice('internal.planAlbums.'.length),input):await s.call(method,input)}}catch(e){return{ok:false,error:{code:e.message}}}}});
let tail=Promise.resolve();readline.createInterface({input:process.stdin}).on('line',line=>{tail=tail.then(async()=>{const q=JSON.parse(line);try{let value;if(q.method==='runtime')value={appVersion:require(path.resolve('package.json')).version,packaged:false,mode:'production',previewFixture:true};else if(q.method==='__fixture.materials')value=await require('./plan-ui-materials.cjs')(s);else if(q.method==='__fixture.tick')value=require(path.resolve('output/unified-plan-integration/core.cjs')).tickPlanCenter(s);else if(q.method==='__fixture.asset'){const loc=s.locate(q.input.id);value={mime:s.get('assets',q.input.id).mime,base64:fs.readFileSync(loc.file).toString('base64')}}else if(q.method==='__fixture.state')value=s.planCenterService().list();else if(['planAlbums.capabilities','planAlbums.refresh','planAlbums.confirm','planAlbums.reconcile'].includes(q.method))value=await albumBroker.ui(q.method.slice('planAlbums.'.length),validate(q.method,q.input??{}));else value=await s.call(q.method,q.input??{});process.stdout.write(JSON.stringify({id:q.id,result:{ok:true,value}})+'\n')}catch(e){process.stdout.write(JSON.stringify({id:q.id,result:{ok:false,error:{code:e.message,message:e.message}}})+'\n')}})}).on('close',()=>tail.finally(()=>s.close()));
